command:
timeout 110 bash -c 'node --input-type=module -e '\''import {audit} from "./scripts/checks/people.mjs";
import {readFileSync,readdirSync} from "node:fs";
import {createHash} from "node:crypto";
import {spawnSync} from "node:child_process";
const checks=[];await audit({checks});console.log(JSON.stringify({kind:"runtime-route-census",checks}));
const counter=spawnSync(process.execPath,["scripts/count-loc.mjs"],{encoding:"utf8"});process.stdout.write(counter.stdout);process.stderr.write(counter.stderr);if(counter.status!==0)process.exit(counter.status??1);
const hashes=Object.fromEntries(["scripts/count-loc.mjs","package-lock.json"].map(file=>[file,createHash("sha256").update(readFileSync(file)).digest("hex")]));
const files=[];function visit(path){for(const entry of readdirSync(path,{withFileTypes:true})){const file=path+"/"+entry.name;if(entry.isDirectory())visit(file);else if(/\.(?:js|jsx|mjs|cjs)$/.test(file)){const source=readFileSync(file,"utf8");files.push({file,physical:source.split("\n").length-(source.endsWith("\n")?1:0),sha256:createHash("sha256").update(source).digest("hex")});}}}
for(const pkg of ["shared","server","web","cli"])visit("packages/"+pkg+"/src");visit("packages/cli/bin");files.sort((a,b)=>b.physical-a.physical||a.file.localeCompare(b.file));
const excessive=files.filter(file=>file.physical>999);console.log(JSON.stringify({kind:"source-identity-size",hashes,productionFileCount:files.length,largest:files.slice(0,12),excessive}));if(excessive.length)process.exit(1);'\'''

